  [23486] = { "リッピングバラバラに次元の壁は、あなたがWinterspringでEverlookに転送します。時にはゴブリンエンジニアリングはすべてに約ある何が発生し、それ 'sの技術的な問題があります！", nil, 0x10772790, nil, "um" },
  [23489] = { "安全にTanarisでGadgetzanに自分自身を運ぶ！安全を重視！このデバイスを使用しているうん、何も悪い、これまで起こりませんでした！", nil, 0x3f2f109f, nil, "um" },
