  [23509] = { "Frostwolf Howlerを召喚/帰還します。\n非常に速いマウントです。", "地上での移動速度が$N1%上昇します。", 0xf80cc58f, 0x2195529a, "uu" },
  [23510] = { "Stormpike Battle Chargerを召喚/\n帰還します。非常に速いマウントです。", "地上での移動速度が$N1%上昇します。", 0xb54c79dc, 0x2195529a, "uu" },
  [23514] = { "Aerie Peakの中央にある井戸の近くに置いてください。あの汚らわしいドワーフの犬どもに覚悟を見せてやりましょう！ そして逃げてください……", nil, 0x45230a81, nil, "um" },
