  [23531] = { "右クリックで小さいgreen dragonを\n召喚/退散します。", nil, 0x97b27314, nil, "um" },
  [23538] = { "体力 $N1のBattle Standardを設置します。Battle Standardから$N2ヤード以内にいるパーティメンバー全員の最大ダメージが$N3%上昇します。効果時間は$D1です。Alterac Valleyでのみ使用できます。", nil, 0x36036ad7, nil, "um" },
  [23539] = { "体力 $N1のBattle Standardを設置します。Battle Standardから$N2ヤード以内にいるパーティメンバー全員のダメージが$N3%上昇します。効果時間は$D1です。Alterac Valleyでのみ使用できます。", nil, 0x5fb70f2c, nil, "um" },
  [23540] = { "$D1かけて体力を$N1、マナを$N2回復します。回復中は座っている必要があります。Warsong Gulch内でのみ使用できます。", "毎秒体力を$N1、マナを$N2回復します。", 0xbd6b05fa, 0x41faa520, "uu" },
  [23541] = { "$D1かけて体力を$N1、マナを$N2回復します。回復中は座っている必要があります。Warsong Gulch内でのみ使用できます。", nil, 0xc9dccdbe, nil, "um" },
  [23542] = { "$D1かけて体力を$N1、マナを$N2回復します。回復中は座っている必要があります。Warsong Gulch内でのみ使用できます。", nil, 0xbb141891, nil, "um" },
  [23560] = { "Mend Petの射程を$N1%、効果を$N2%増加させます。さらにコストを$N3%軽減します。", nil, 0x75a4324f, nil, "um" },
