  [23568] = { "$D1かけて$N1のダメージを回復します。Warsong Gulch内でのみ使用できます。", "$N2秒ごとに$N1のダメージを回復します。", 0xc6a65c36, 0x4b6eb5c1, "uu" },
  [23569] = { "$D1かけて$N1のダメージを回復します。Warsong Gulch内でのみ使用できます。", "$N2秒ごとに$N1のダメージを回復します。", 0xc6a65c36, 0x4b6eb5c1, "uu" },
  [23584] = { "オフハンド武器のダメージを$N1%、オフハンドによる怒り生成量を$N2%、オフハンド攻撃の命中率を$N3%上昇させます。", nil, 0x31102645, nil, "um" },
  [23592] = { "対象に$N1のNatureダメージを与えます。", nil, 0x37bddcc4, nil, "um" },
