  [23698] = { "$D1かけてマナを$N1回復します。飲んでいる間は座っている必要があります。さらに、$D2の間精神を$N3上昇させます。", "毎秒マナを$N1回復します。", 0x661ecf95, 0x338019ff, "uu" },
  [23701] = { "装備者は$N1%の確率で、体力とマナが$N2%の状態で蘇生できるようになります。", nil, 0x795b6ec4, nil, "um" },
  [23719] = { "$D1の間、筋力を$N1上げます。", "筋力が$N1増加しています。", 0xeb1f7146, 0x90d8a2f8, "uu" },
  [23720] = { "$D1の間ペットを強化し、ペットのダメージを$N1%、ペットのアーマーを$N2%増加させます。この呪文はImp、Succubus、Incubus、Voidwalker、Felhunterにのみ効果があります。", "与えるダメージが$N1%増加します。\nアーマーが$N2%増加します。", 0x4adba820, 0x4da17a8e, "uu" },
  [23721] = { "Arcaneのエネルギーを宿し、$D1以内に放つ次のArcane Shotを対象の位置で炸裂させます。Arcane Detonationは対象の周囲の敵に$N2のダメージを与えます。", "次のArcane ShotがArcane Detonationを発生させます。", 0xb0483c28, 0xb858471f, "uu" },
  [23723] = { "精神を加速させ、$D1の間メイジの詠唱速度を$N1%上昇させます。", "詠唱速度が$N1%上昇しています。", 0x54f6c7f3, 0xb128184e, "uu" },
  [23724] = { "$D1の間、ドルイドのすべての変身フォームのマナコストを$N1%軽減します。", "変身のマナコストが$N1%減少しています。", 0x742b2612, 0x52ea9a5e, "uu" },
  [23725] = { "最大体力の$N1%を回復し、$N3秒間最大体力を$N2%増加させます。", "最大体力が$N1%増加しています。", 0x1e2b7615, 0xfdd831f0, "uu" },
  [23726] = { "$D1の間、対象にローグの毒を付与する確率を$N1%上昇させます。", "目標に毒を付与する確率が$N1%上昇しています。", 0xff956cbd, 0x88c80e24, "uu" },
  [23733] = { "パラディンに光のエネルギーを与え、$D1の間近接攻撃速度を$N1%、呪文詠唱速度を$N2%上昇させます。", "攻撃速度が$N1%上昇しています。\n詠唱速度が$N2%上昇しています。", 0x5d3efaf4, 0x5ddb22a8, "uu" },
  [23734] = { "シャーマンを自然と調和させ、$D1の間呪文ダメージを$N1%増加、回復効果を$N2%向上させ、呪文のマナコストを$N3%増加させます。", "呪文ダメージが$N1%増加しています。\n治療効果が$N2%増加しています。\nマナコストが$N3%増加しています。", 0xd036c831, 0xe6a5f3df, "uu" },
