  [23925] = { "盾で対象を殴りつけ、$N1のダメージを与えます。このダメージはBlock Valueで増加します。さらに$N2%の確率で対象の魔法効果を$N3個解除します。非常に大きな脅威を発生させます。", nil, 0x28cfacbe, nil, "um" },
